typedef struct {
    int *a;
    int sz;
} Set;

typedef struct {
    int parent;
    int rank;
} DSU;

static void dsu_init(DSU *d, int n) {
    for (int i = 1; i <= n; i++) {
        d[i].parent = i;
        d[i].rank = 0;
    }
}

static int dsu_find(DSU *d, int x) {
    if (d[x].parent != x) d[x].parent = dsu_find(d, d[x].parent);
    return d[x].parent;
}

static int dsu_union(DSU *d, int x, int y) {
    x = dsu_find(d, x);
    y = dsu_find(d, y);
    if (x == y) return 0;
    if (d[x].rank < d[y].rank) {
        d[x].parent = y;
    } else if (d[x].rank > d[y].rank) {
        d[y].parent = x;
    } else {
        d[y].parent = x;
        d[x].rank++;
    }
    return 1;
}

typedef struct {
    int l, r;
    int set_id;
} Interval;

static int cmp_interval(const void *p1, const void *p2) {
    const Interval *a = (const Interval *)p1;
    const Interval *b = (const Interval *)p2;
    if (a->r != b->r) return a->r - b->r;
    return a->l - b->l;
}

