    int *par = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 0; i <= N; i++) par[i] = i;

    int findp(int x);
    /* C doesn't allow nested named functions portably, emulate with macro-less inline style below */
    /* We'll use iterative path compression helper via static arrays not possible here, so local lambda impossible. */
    /* Rewrite using a small loop macro-like function through GNU extension avoided. */

    /* store answers */
    int *U = (int *)malloc((N) * sizeof(int));
    int *V = (int *)malloc((N) * sizeof(int));

    DSU *dsu = (DSU *)malloc((N + 1) * sizeof(DSU));
    dsu_init(dsu, N);

    /* predecessor DSU functions manually inline */
    for (int idx = 1; idx <= N - 1; idx++) {
        int l = iv[idx].l, r = iv[idx].r, id = iv[idx].set_id;

        int x = r - 1;
        int y = x;
