        }

        U[id] = x;
        V[id] = r;

        dsu_union(dsu, x, r);

        /* remove x from available set: union x to x-1 in predecessor structure */
        int a = x, b = x - 1;
        while (par[b] != b) {
            par[b] = par[par[b]];
            b = par[b];
        }
        par[a] = b;
    }

    /* verify connectivity */
    int root = dsu_find(dsu, 1);
    for (int i = 2; i <= N; i++) {
        if (dsu_find(dsu, i) != root) {
            printf("NO\n");
            return 0;
        }
    }

    /* final validation: each chosen pair must lie in original set */
    /* Since x and r are in [min,max] but not necessarily in original set, this greedy is only valid
       if original sets are intervals. For general subsets, we must ensure membership directly.
       Therefore we repair approach: choose edges only among original elements using a leaf-elimination construction.
    */

    /* Restart with correct general solution:
       Let cnt[v] = number of sets containing v.
       Repeatedly find a vertex v with cnt[v] = 1. Let the unique remaining set be S.
       In any tree realization, v must be a leaf connected using edge of S.
       Remove S, and connect v later to some other vertex in S still alive.
       This is analogous to Prüfer decoding and is sufficient/necessary.
    */

    /* clean previous memory not necessary for judge, but we will reuse arrays. */
    for (int i = 1; i <= N - 1; i++) { U[i] = V[i] = 0; }

    int *cnt = (int *)calloc(N + 1, sizeof(int));
    int **pos = (int **)malloc((N + 1) * sizeof(int *));
    int *deg = (int *)calloc(N + 1, sizeof(int));

    for (int v = 1; v <= N; v++) deg[v] = 0;
    for (int i = 1; i <= N - 1; i++) {
        for (int j = 0; j < E[i].sz; j++) deg[E[i].a[j]]++;
    }
    for (int v = 1; v <= N; v++) {
        pos[v] = (int *)malloc(deg[v] * sizeof(int));
        deg[v] = 0;
    }
    for (int i = 1; i <= N - 1; i++) {
        for (int j = 0; j < E[i].sz; j++) {
            int v = E[i].a[j];
            pos[v][deg[v]++] = i;
            cnt[v]++;
        }
    }

    int *aliveSet = (int *)malloc((N) * sizeof(int));
    int *aliveV = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N - 1; i++) aliveSet[i] = 1;
    for (int v = 1; v <= N; v++) aliveV[v] = 1;

    int *queue = (int *)malloc((N + 5) * sizeof(int));
    int qh = 0, qt = 0;
    for (int v = 1; v <= N; v++) if (cnt[v] == 1) queue[qt++] = v;

    int *usedSet = (int *)calloc(N, sizeof(int));
    int *orderSet = (int *)malloc((N) * sizeof(int));
    int *leafOfSet = (int *)malloc((N) * sizeof(int));
    int ord = 0;

    while (qh < qt) {
        int v = queue[qh++];
        if (!aliveV[v] || cnt[v] != 1) continue;

        int sid = -1;
        for (int t = 0; t < deg[v]; t++) {
            int s = pos[v][t];
            if (aliveSet[s]) {
                sid = s;
                break;
            }
        }
        if (sid == -1) continue;

        aliveSet[sid] = 0;
        usedSet[sid] = 1;
        orderSet[ord] = sid;
        leafOfSet[ord] = v;
        ord++;
        aliveV[v] = 0;

        for (int j = 0; j < E[sid].sz; j++) {
            int x = E[sid].a[j];
            if (cnt[x] > 0) {
                cnt[x]--;
                if (aliveV[x] && cnt[x] == 1) queue[qt++] = x;
            }
        }
    }

    if (ord != N - 1) {
        printf("NO\n");
        return 0;
    }

    int last = -1;
    for (int v = 1; v <= N; v++) if (aliveV[v]) { last = v; break; }
    if (last == -1) {
        printf("NO\n");
        return 0;
    }

    for (int i = ord - 1; i >= 0; i--) {
        int sid = orderSet[i];
        int leaf = leafOfSet[i];

        int other = -1;
        if (i == ord - 1) {
            /* At this moment only 'last' remains alive among future core */
            for (int j = 0; j < E[sid].sz; j++) {
                if (E[sid].a[j] == last) {
                    other = last;
                    break;
                }
            }
        } else {
            for (int j = 0; j < E[sid].sz; j++) {
                int x = E[sid].a[j];
                if (aliveV[x]) {
                    other = x;
                    break;
                }
            }
        }
        if (other == -1 || other == leaf) {
            printf("NO\n");
            return 0;
        }
        U[sid] = leaf;
        V[sid] = other;
        aliveV[leaf] = 1;
    }

    /* verify tree */
    dsu_init(dsu, N);
    for (int i = 1; i <= N - 1; i++) {
        if (U[i] <= 0 || V[i] <= 0 || U[i] == V[i]) {
            printf("NO\n");
            return 0;
        }
        int ok1 = 0, ok2 = 0;
        for (int j = 0; j < E[i].sz; j++) {
            if (E[i].a[j] == U[i]) ok1 = 1;
            if (E[i].a[j] == V[i]) ok2 = 1;
        }
        if (!ok1 || !ok2) {
            printf("NO\n");
            return 0;
        }
        if (!dsu_union(dsu, U[i], V[i])) {
            printf("NO\n");
            return 0;
        }
    }
    root = dsu_find(dsu, 1);
    for (int i = 2; i <= N; i++) {
        if (dsu_find(dsu, i) != root) {
            printf("NO\n");
            return 0;
        }
    }

    printf("YES\n");
    for (int i = 1; i <= N - 1; i++) {
        printf("%d %d\n", U[i], V[i]);
    }

    return 0;
}

