int main(){
    int N; cin>>N;
    vector<vector<int>> E(N-1);
    for(int i=0;i<N-1;i++){int k;cin>>k;E[i].resize(k);for(auto&x:E[i])cin>>x,x--;}
    // enumerate all edges
    vector<tuple<int,int,int>> edges; // (u,v,group)
    for(int i=0;i<N-1;i++)
        for(int a=0;a<(int)E[i].size();a++)
            for(int b=a+1;b<(int)E[i].size();b++)
                edges.push_back({E[i][a],E[i][b],i});
    int M=edges.size();
    vector<bool> inS(M,false);
    vector<int> groupOf(M); for(int i=0;i<M;i++) groupOf[i]=get<2>(edges[i]);
    // matroid intersection
    for(int iter=0;iter<N-1;iter++){
        // BFS augmenting path
        vector<int> prev(M,-2); // -2=unvisited, -1=source
        queue<int> q;
        // sources: not in S, group not covered
        set<int> covered;
        for(int i=0;i<M;i++) if(inS[i]) covered.insert(groupOf[i]);
        for(int y=0;y<M;y++) if(!inS[y]&&!covered.count(groupOf[y])){prev[y]=-1;q.push(y);}
        int sink=-1;
        // check if y alone is forest
        auto isForest=[&](vector<int>&sel)->bool{
            for(int i=1;i<=N;i++) par[i]=i;
            for(int e:sel){auto[u,v,g]=edges[e];if(find(u)==find(v))return false;par[find(u)]=find(v);}
            return true;
        };
        while(!q.empty()&&sink==-1){
            int y=q.front();q.pop();
            if(!inS[y]){// check sink: S+y is forest?
                vector<int> sel; for(int i=0;i<M;i++) if(inS[i]) sel.push_back(i); sel.push_back(y);
                if(isForest(sel)){sink=y;break;}
                // y->x: x in S, S-x+y forest
                for(int x=0;x<M;x++) if(inS[x]&&prev[x]==-2){
                    vector<int> s2; for(int i=0;i<M;i++) if(inS[i]&&i!=x) s2.push_back(i); s2.push_back(y);
                    if(isForest(s2)){prev[x]=y;q.push(x);}
                }
            } else {// x in S, x->y: not in S, S-x+y ok for partition (y's group != x's group or y's group uncovered without x... group of y not in covered\{groupOf[x]})
                int x=y;
                set<int> cov2; for(int i=0;i<M;i++) if(inS[i]&&i!=x) cov2.insert(groupOf[i]);
                for(int yy=0;yy<M;yy++) if(!inS[yy]&&prev[yy]==-2&&!cov2.count(groupOf[yy])){prev[yy]=x;q.push(yy);}
            }
        }
        if(sink==-1) break;
        // augment
        int cur=sink; while(cur!=-1&&prev[cur]!=-1){int p=prev[cur];inS[cur]=true;inS[p]=false;cur=prev[p];} if(cur!=-1)inS[cur]=true;
    }
    int cnt=0; for(int i=0;i<M;i++) if(inS[i]) cnt++;
    if(cnt<N-1){cout<<"No\n";return 0;}
    cout<<"Yes\n";
    for(int i=0;i<M;i++) if(inS[i]){auto[u,v,g]=edges[i];cout<<u+1<<" "<<v+1<<"\n";}
}

#include <bits/stdc++.h>
using namespace std;

/*
We have N-1 subsets E_i of {1..N}. For each set we must choose one edge
(u_i, v_i), both endpoints inside E_i, so that all chosen edges form a tree.

Key fact (hypergraph/tree version of Hall):
Such a selection exists iff for every collection of k sets, the union of their
vertices has size at least k+1.
Equivalently, if we build a bipartite graph:
  left: sets 1..N-1
  right: vertices 1..N
  edge i-x iff x in E_i
then we need an orientation/selection where each set gets two distinct incident
vertices and overall the chosen incidence graph is a tree on right side.

A constructive way:
Repeatedly find a vertex that belongs to exactly one remaining set.
If a tree solution exists, such a vertex always exists in the current instance.
Suppose vertex v appears only in set e. Then in any tree solution, the edge for
e must connect v to some other vertex in e. So we can remove v and set e, and
later connect v back to the representative of the reduced component.

This leads to a peeling process similar to Prüfer decoding in reverse.

Algorithm:
- Maintain remaining sets and vertices.
- For each vertex, keep list of incident remaining sets and current degree
  (# remaining incident sets).
- Queue all vertices of degree 1.
- Repeatedly pop such a vertex v. Let e be its unique remaining incident set.
  Remove set e. For every vertex x in e still alive, decrement its degree.
  Among vertices of e except v, choose one alive vertex rep[e] (any).
  Record pair (e, v, rep[e]) meaning later edge of e will be (v, root_of_rep[e]).
  Mark v removed as well.
- If after peeling all sets are removed, success.
- If stuck before removing all sets => impossible.

Why reconstruction works:
When removing e due to leaf vertex v, the rest of vertices in e stay in the
reduced instance. In the final tree, e can connect v to the connected component
represented by any surviving vertex in e at that time. Using DSU-like parent
chasing over recorded representatives reconstructs actual endpoint.

At the very end exactly one vertex remains alive. Process recorded removals in
reverse:
- Let root[x] be current representative vertex of component containing original
  alive vertex x; initially root[last_alive] = last_alive.
- For recorded (e, leaf=v, rep=r), set chosen edge for e = (v, root_of(r)),
  and then component containing v becomes merged, so root[v] = v? Actually for
  further reverse steps, older removed leaves may refer to rep=r, not to v.
  We only need a DSU over vertices according to built tree edges in reverse.
  Simpler: use DSU and for each component store one actual vertex representative.
  Initially each alive vertex singleton.
  Reverse step:
    a = v, b = repr(find(r))
    choose edge (a,b)
    union(a,b)
This works because r is already in reconstructed reduced tree.

Need ensure sets of size <2 impossible immediately.

Complexities O(total membership * alpha(N)).
*/

struct DSU {
    vector<int> p, sz, any;
    DSU(int n = 0) { init(n); }
    void init(int n) {
        p.resize(n + 1);
        sz.assign(n + 1, 1);
        any.resize(n + 1);
        for (int i = 1; i <= n; ++i) p[i] = any[i] = i;
    }
    int find(int x) {
        if (p[x] == x) return x;
        return p[x] = find(p[x]);
    }
    int repr(int x) { return any[find(x)]; }
    void unite(int a, int b) {
        a = find(a); b = find(b);
        if (a == b) return;
        if (sz[a] < sz[b]) swap(a, b);
        p[b] = a;
        sz[a] += sz[b];
        // keep any[a] unchanged
    }
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;
    int M = N - 1;

    vector<vector<int>> sets(M + 1);
    vector<vector<int>> inc(N + 1);

    for (int i = 1; i <= M; ++i) {
        int k;
        cin >> k;
        sets[i].resize(k);
        for (int j = 0; j < k; ++j) {
            cin >> sets[i][j];
            inc[sets[i][j]].push_back(i);
        }
        if (k < 2) {
            cout << "NO\n";
            return 0;
        }
    }

    vector<int> deg(N + 1, 0);
    for (int v = 1; v <= N; ++v) deg[v] = (int)inc[v].size();

    vector<char> aliveV(N + 1, 1), aliveE(M + 1, 1);
    queue<int> q;
    for (int v = 1; v <= N; ++v) if (deg[v] == 1) q.push(v);

    struct Step { int e, leaf, rep; };
    vector<Step> steps;
    steps.reserve(M);

    int removedEdges = 0;

    while (!q.empty()) {
        int v = q.front(); q.pop();
        if (!aliveV[v] || deg[v] != 1) continue;

        int e = -1;
        for (int id : inc[v]) {
            if (aliveE[id]) { e = id; break; }
        }
        if (e == -1) continue;

        int rep = -1;
        for (int x : sets[e]) {
            if (aliveV[x] && x != v) {
                rep = x;
                break;
            }
        }
        if (rep == -1) {
            cout << "NO\n";
            return 0;
        }

        steps.push_back({e, v, rep});

        aliveE[e] = 0;
        removedEdges++;

        for (int x : sets[e]) {
            if (!aliveV[x]) continue;
            deg[x]--;
            if (deg[x] == 1) q.push(x);
        }
        aliveV[v] = 0;
    }

    if (removedEdges != M) {
        cout << "NO\n";
        return 0;
    }

    cout << "YES\n";

    vector<pair<int,int>> ans(M + 1);
    DSU dsu(N);

    // reverse reconstruction
    for (int i = (int)steps.size() - 1; i >= 0; --i) {
        int e = steps[i].e;
        int leaf = steps[i].leaf;
        int rep = steps[i].rep;
        int b = dsu.repr(rep);
        ans[e] = {leaf, b};
        dsu.unite(leaf, b);
    }

    for (int i = 1; i <= M; ++i) {
        cout << ans[i].first << ' ' << ans[i].second << '\n';
    }

    return 0;
}

