public class Main {
    static class DSU {
        int[] parent, rank;
        DSU(int n) {
            parent = new int[n];
            rank = new int[n];
            for (int i = 0; i < n; i++) parent[i] = i;
        }
        int find(int x) {
            if (parent[x] != x) parent[x] = find(parent[x]);
            return parent[x];
        }
        boolean union(int a, int b) {
            int ra = find(a), rb = find(b);
            if (ra == rb) return false;
            if (rank[ra] < rank[rb]) {
                int tmp = ra; ra = rb; rb = tmp;
            }
            parent[rb] = ra;
            if (rank[ra] == rank[rb]) rank[ra]++;
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        List<int[]>[] sets = new ArrayList[N - 1];
        for (int i = 0; i < N - 1; i++) {
            int k = sc.nextInt();
            sets[i] = new ArrayList<>();
            int[] arr = new int[k];
            for (int j = 0; j < k; j++) {
                arr[j] = sc.nextInt() - 1; // zero-based
            }
            // store all pairs from this set
            for (int a = 0; a < k; a++) {
                for (int b = a + 1; b < k; b++) {
                    sets[i].add(new int[]{arr[a], arr[b]});
                }
            }
        }

        DSU dsu = new DSU(N);
        int[][] edges = new int[N - 1][2];
        boolean[] usedSet = new boolean[N - 1];

        // First pass: use an edge that connects two components
        for (int i = 0; i < N - 1; i++) {
            for (int[] edge : sets[i]) {
                int u = edge[0], v = edge[1];
                if (dsu.find(u) != dsu.find(v)) {
                    dsu.union(u, v);
                    edges[i] = new int[]{u, v};
                    usedSet[i] = true;
                    break;
                }
            }
        }

        // Check connectivity
        int root = dsu.find(0);
        for (int i = 1; i < N; i++) {
            if (dsu.find(i) != root) {
                System.out.println(-1);
                return;
            }
        }

        // Fill remaining sets with any edge (graph already connected)
        for (int i = 0; i < N - 1; i++) {
            if (!usedSet[i]) {
                edges[i] = sets[i].get(0);
            }
        }

        // Output
        for (int i = 0; i < N - 1; i++) {
            System.out.println((edges[i][0] + 1) + " " + (edges[i][1] + 1));
        }
    }
}

