public class Main {
    static class FastScanner {
        private final InputStream in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        FastScanner(InputStream is) {
            in = is;
        }

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class EdgeCand {
        int color, u, v;
        EdgeCand(int color, int u, int v) {
            this.color = color;
            this.u = u;
            this.v = v;
        }
    }

    static class ChosenEdge {
        int u, v;
        ChosenEdge(int u, int v) {
            this.u = u;
            this.v = v;
        }
    }

    static int N, C;
    static ArrayList<EdgeCand> elems = new ArrayList<>();
    static ArrayList<Integer>[] chosenAdj;
    static boolean[] inI;
    static int[] chosenByColor; // selected element index per color, -1 if none

    static class DSU {
        int[] p, r;
        DSU(int n) {
            p = new int[n + 1];
            r = new int[n + 1];
            for (int i = 1; i <= n; i++) p[i] = i;
        }
        int find(int x) {
            while (p[x] != x) {
                p[x] = p[p[x]];
                x = p[x];
            }
            return x;
        }
        boolean union(int a, int b) {
            a = find(a); b = find(b);
            if (a == b) return false;
            if (r[a] < r[b]) { int t = a; a = b; b = t; }
            p[b] = a;
            if (r[a] == r[b]) r[a]++;
            return true;
        }
    }

    static boolean graphicAddable(int eIdx) {
        DSU dsu = new DSU(N);
        for (int i = 0; i < elems.size(); i++) {
            if (inI[i]) {
                EdgeCand e = elems.get(i);
                dsu.union(e.u, e.v);
            }
        }
        EdgeCand e = elems.get(eIdx);
        return dsu.find(e.u) != dsu.find(e.v);
    }

    static List<Integer> pathEdgesInForest(int src, int dst) {
        int[] parentV = new int[N + 1];
        int[] parentE = new int[N + 1];
        Arrays.fill(parentV, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(src);
        parentV[src] = 0;
        while (!q.isEmpty()) {
            int x = q.poll();
            if (x == dst) break;
            for (int eIdx : chosenAdj[x]) {
                EdgeCand e = elems.get(eIdx);
                int y = e.u ^ e.v ^ x;
                if (parentV[y] == -1) {
                    parentV[y] = x;
                    parentE[y] = eIdx;
                    q.add(y);
                }
            }
        }
        ArrayList<Integer> path = new ArrayList<>();
        int cur = dst;
        while (cur != src) {
            path.add(parentE[cur]);
            cur = parentV[cur];
        }
        return path;
    }

    static int[] findAugmentingPath() {
        int m = elems.size();
        int SRC = m, SNK = m + 1;
        ArrayList<Integer>[] g = new ArrayList[m + 2];
        for (int i = 0; i < g.length; i++) g[i] = new ArrayList<>();

        DSU dsu = new DSU(N);
        for (int i = 0; i < m; i++) if (inI[i]) {
            EdgeCand e = elems.get(i);
            dsu.union(e.u, e.v);
        }

        for (int e = 0; e < m; e++) if (!inI[e]) {
            EdgeCand ce = elems.get(e);

            // M1: source -> e if addable
            if (dsu.find(ce.u) != dsu.find(ce.v)) {
                g[SRC].add(e);
            } else {
                // unique path in forest between endpoints
                List<Integer> cyc = pathEdgesInForest(ce.u, ce.v);
                for (int f : cyc) g[f].add(e);
            }

            // M2: e -> sink if color unused, else e -> selected same color
            int sel = chosenByColor[ce.color];
            if (sel == -1) g[e].add(SNK);
            else g[e].add(sel);
        }

        int[] prev = new int[m + 2];
        Arrays.fill(prev, -1);
        ArrayDeque<Integer> q = new ArrayDeque<>();
        q.add(SRC);
        prev[SRC] = SRC;
        while (!q.isEmpty() && prev[SNK] == -1) {
            int x = q.poll();
            for (int y : g[x]) {
                if (prev[y] == -1) {
                    prev[y] = x;
                    q.add(y);
                    if (y == SNK) break;
                }
            }
        }
        if (prev[SNK] == -1) return null;
        return prev;
    }

    static void rebuildChosenAdj() {
        chosenAdj = new ArrayList[N + 1];
        for (int i = 1; i <= N; i++) chosenAdj[i] = new ArrayList<>();
        Arrays.fill(chosenByColor, -1);
        for (int i = 0; i < elems.size(); i++) if (inI[i]) {
            EdgeCand e = elems.get(i);
            chosenAdj[e.u].add(i);
            chosenAdj[e.v].add(i);
            chosenByColor[e.color] = i;
        }
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner(System.in);
        N = fs.nextInt();
        C = N - 1;

        for (int i = 0; i < C; i++) {
            int k = fs.nextInt();
            int[] a = new int[k];
            for (int j = 0; j < k; j++) a[j] = fs.nextInt();
            for (int x = 0; x < k; x++) {
                for (int y = x + 1; y < k; y++) {
                    elems.add(new EdgeCand(i, a[x], a[y]));
                }
            }
        }

        inI = new boolean[elems.size()];
        chosenByColor = new int[C];
        Arrays.fill(chosenByColor, -1);
        rebuildChosenAdj();

        int size = 0;
        while (true) {
            int[] prev = findAugmentingPath();
            if (prev == null) break;

            int m = elems.size();
            int SRC = m, SNK = m + 1;
            int cur = prev[SNK];
            while (cur != SRC) {
                inI[cur] = !inI[cur];
                cur = prev[cur];
            }
            rebuildChosenAdj();
            size++;
            if (size == N - 1) break;
        }

        if (size != N - 1) {
            System.out.println("NO");
            return;
        }

        // Verify connected/tree and all colors used
        for (int i = 0; i < C; i++) {
            if (chosenByColor[i] == -1) {
                System.out.println("NO");
                return;
            }
        }

        System.out.println("YES");
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < C; i++) {
            EdgeCand e = elems.get(chosenByColor[i]);
            sb.append(e.u).append(' ').append(e.v).append('\n');
        }
        System.out.print(sb.toString());
    }
}
